INSERT INTO `ai_agent_knowledge` (`category`, `keywords`, `question`, `answer`, `sort_order`) VALUES
('FAQ', 'plate number, show plate details, প্লেট নম্বর, প্লেটের ডিটেলস, প্লেটের সাইজ, plate size, cylinder, সিলিন্ডার, P-', 'প্লেট নম্বর দিয়ে কীভাবে ডিটেলস খুঁজবো?', 'আপনি নির্দিষ্ট প্লেটের ডিটেলস জানতে প্লেট নম্বর লিখে সার্চ করতে পারেন। উদাহরণস্বরূপ: "P-1234 প্লেটের ডিটেলস দেখাও", "P-1234 প্লেটের সাইজ কত?", "P-1234 প্লেটের জন্য কোন সিলিন্ডার লাগে?" বা "P-101 প্লেটটি কবে রিসিভ হয়েছে?"।', 20),
('FAQ', 'job name, design name, label name, জব, ডিজাইনের নাম, লেবেল, কোকা-কোলা, mango juice, amul', 'জব বা ডিজাইনের নাম দিয়ে কীভাবে প্লেট খুঁজবো?', 'যেকোনো জব বা ডিজাইনের নাম উল্লেখ করে তার প্লেটের তথ্য জানতে পারেন। উদাহরণস্বরূপ: "কোকা-কোলা লেবেলের প্লেট কোনটা?", "Mango Juice জবের জন্য প্লেট ডিটেলস দাও", বা "Amul-এর প্লেটগুলো কী কী?"।', 21),
('FAQ', 'cylinder size, magnetic cylinder, সিলিন্ডার সাইজ, 104, 120, 80 cylinder', 'সিলিন্ডারের সাইজ দিয়ে প্লেট খোঁজা যাবে কি?', 'হ্যাঁ, আপনি সিলিন্ডারের সাইজ উল্লেখ করে প্লেট খুঁজতে পারেন। যেমন: "104 T সিলিন্ডারের কয়টি প্লেট আছে?", "120 সিলিন্ডারের সব প্লেটের লিস্ট দাও", বা "কোন কোন জবে 80 সিলিন্ডার ব্যবহার হয়?"।', 22),
('FAQ', 'paper type, paper size, chromo paper, pp clear, 200mm, পেপার টাইপ, পেপার সাইজ, ক্রোম পেপার', 'পেপার টাইপ বা সাইজ দিয়ে প্লেট সার্চ করা যায়?', 'হ্যাঁ, পেপারের ধরন বা সাইজ দিয়ে আপনি প্লেট সার্চ করতে পারেন। উদাহরণস্বরূপ: "Chromo পেপারের জন্য কোন কোন প্লেট তৈরি আছে?", "PP Clear-এর প্লেটগুলো দেখাও", বা "পেপার সাইজ 200mm এর প্লেটগুলো দেখাও"।', 23),
('FAQ', 'color information, cmyk, special color, কালার, কালারের তথ্য, স্পেশাল কালার, 4 colors', 'প্লেটের কালার সম্পর্কে কীভাবে জানতে পারি?', 'প্লেটের কালার সংক্রান্ত তথ্যের জন্য আপনি জিজ্ঞাসা করতে পারেন: "P-101 প্লেটে মোট কয়টি কালার ব্যবহার হয়েছে?", "P-123 প্লেটে স্পেশাল কালার (Special Color) কী কী আছে?", বা "কোন প্লেটগুলোতে ৪টির বেশি কালার আছে?"।', 24),
('FAQ', 'gap, repeat dimensions, gap h, gap v, গ্যাপ, রিপিট, horizontal gap, vertical gap', 'প্লেটের গ্যাপ এবং রিপিট (Gap & Repeat) ভ্যালু কীভাবে জানবো?', 'গ্যাপ এবং রিপিট ভ্যালু জানতে প্লেট নম্বর উল্লেখ করে প্রশ্ন করতে পারেন। উদাহরণ: "P-101 প্লেটের Horizontal Gap (Gap H) এবং Vertical Gap (Gap V) কত?", "P-123 প্লেটের রিপিট (Repeat) ভ্যালু কত?", বা "150mm রিপিটের প্লেটগুলো দেখাও"।', 25),
('FAQ', 'combination queries, mixed queries, 104 cylinder chromo, মিশ্রিত প্রশ্ন', 'একাধিক শর্ত দিয়ে (Combination) প্লেট খোঁজা যায়?', 'অবশ্যই! আপনি একাধিক শর্ত একসাথে মিলিয়ে প্রশ্ন করতে পারেন। যেমন: "104 সিলিন্ডারের Chromo পেপারের প্লেট দেখাও" বা "Make By \'Navkar\'-এর 120 সিলিন্ডারের প্লেটগুলো কী কী?"।', 26),
('FAQ', 'math calculation, total labels, paper length, calculate, গাণিতিক প্রশ্ন, মোট লেবেল, কত পেপার লাগবে, কত রানিং মিটার', 'প্লেট ডাটা ব্যবহার করে কীভাবে পেপারের হিসাব (Calculation) করা যায়?', 'আপনি নির্দিষ্ট প্লেটের নাম বা নম্বর এবং কোয়ান্টিটি উল্লেখ করে পেপার হিসাব করতে পারেন। উদাহরণস্বরূপ: "/plate How many running meters of paper do I need to print 100,000 labels for \'grass\'?", বা "we want to printing item \'blue 500ml\' for 50000 quantity, how many paper required?"', 27);
